const TYPE_KEY: Record<ProductType, string> = { frame: 'productType.frame', sunglasses: 'productType.sunglasses', contact_lens: 'productType.contact_lens', eye_hygiene: 'productType.eye_hygiene', accessory: 'productType.accessory' };
const STOCK_KEY: Record<StockStatus, string> = { in_stock: 'stock.in_stock', out_of_stock: 'stock.out_of_stock', backorder: 'stock.backorder' };
/** Resolves a label key for the active language. */
function useLabels() {
  const { t } = useLanguage();
  return { t, type: (value: ProductType) => t(TYPE_KEY[value] ?? TYPE_KEY.accessory), stock: (value: StockStatus) => t(STOCK_KEY[value] ?? STOCK_KEY.in_stock) };
}
const productStatusColor = (active?: boolean) => active ? { bg: colors.greenSoft, text: colors.green } : { bg: '#FFF0F1', text: colors.red };

function money(value: unknown) {
  const amount = Number(value ?? 0);
  return new Intl.NumberFormat(getActiveLanguage() === 'it' ? 'it-IT' : 'en-IE', { style: 'currency', currency: 'EUR' }).format(Number.isFinite(amount) ? amount : 0);
}

function dateText(value?: string | null) {
  if (!value) return null;
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? value : parsed.toLocaleDateString(getActiveLanguage() === 'it' ? 'it-IT' : 'en-IE', { dateStyle: 'medium' });
}

function cleanOptional(value?: string) { const clean = value?.trim(); return clean ? clean : undefined; }
function toNumber(value: string, fallback = 0) { const parsed = Number(value); return Number.isFinite(parsed) ? parsed : fallback; }
function listFrom(value?: string[] | null) { return Array.isArray(value) ? value.join(', ') : ''; }
function listTo(value: string) { return value.split(',').map((entry) => entry.trim()).filter(Boolean); }
function humanize(value: string) { return value.split('_').map((part) => part ? `${part.slice(0, 1).toUpperCase()}${part.slice(1)}` : '').join(' '); }

export function ProductListScreen() {
  const { t } = useLabels();
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<ProductCategory[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchOpen, setSearchOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [filters, setFilters] = useState<ProductListParams>({ sort_by: 'created_at', sort_order: 'desc' });
  const [page, setPage] = useState({ current: 1, last: 1, total: 0 });
  const [loadingMore, setLoadingMore] = useState(false);
  const load = useCallback(async (nextPage = 1, append = false) => {
    try {
      if (append) setLoadingMore(true); else setLoading(true);
      setError(null);
      const response = await productService.getProducts({ ...filters, search: search.trim() || undefined, page: nextPage, per_page: 30 });
      setProducts((current) => append ? [...current, ...response.data] : response.data);
      setPage({ current: response.current_page, last: response.last_page, total: response.total });
    } catch (cause) { setError(getErrorMessage(cause)); }
    finally { setLoading(false); setLoadingMore(false); }
  }, [filters, search]);
  const loadCategories = useCallback(() => { void productService.getCategories().then(setCategories).catch(() => {}); }, []);
  useEffect(loadCategories, [loadCategories]);
  // Search and filter changes are intentionally a server reload, with the
  // standard loading state shown while the filtered catalogue is updated.
  useAutoRefresh(load, true, 20_000, JSON.stringify({ filters, search: search.trim() }));

  return <Screen contentStyle={styles.screenBottom} overlay={<Pressable accessibilityRole="button" accessibilityLabel={t('products.addProductLabel')} onPress={() => router.push('/product-create')} style={styles.fab}><MaterialCommunityIcons name="plus" size={27} color="#FFFFFF" /></Pressable>}>
    <AppHeader title={t('products.title')} right={<View style={styles.headerActions}><Pressable accessibilityLabel={t('products.searchLabel')} onPress={() => setSearchOpen((open) => !open)} style={styles.headerSearch}><MaterialCommunityIcons name="magnify" size={22} color="#3E5877" /></Pressable><MainHeaderActions /></View>} />
    <View style={styles.intro}><Text style={styles.overline}>{t('products.overline')}</Text><Text style={styles.title}>{t('products.pageTitle')}</Text><Text style={styles.subtitle}>{page.total ? t(page.total === 1 ? 'products.subtitleCount' : 'products.subtitleCountPlural', { count: page.total }) : t('products.subtitleDefault')}</Text></View>
    {searchOpen ? <SearchField value={search} onChange={setSearch} onClose={() => { setSearch(''); setSearchOpen(false); }} placeholder={t('products.searchPlaceholder')} /> : null}
    <View style={styles.listTools}><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.toolScroll}>
      <FilterPill label={t('products.filter.all')} active={!filters.is_active && !filters.on_sale && !filters.product_type} onPress={() => setFilters({ sort_by: filters.sort_by, sort_order: filters.sort_order })} />
      <FilterPill label={t('products.filter.live')} active={filters.is_active === true} onPress={() => setFilters((current) => ({ ...current, is_active: true, on_sale: undefined, product_type: undefined }))} />
      <FilterPill label={t('products.filter.inactive')} active={filters.is_active === false} onPress={() => setFilters((current) => ({ ...current, is_active: false, on_sale: undefined, product_type: undefined }))} />
      <FilterPill label={t('products.filter.onSale')} active={filters.on_sale === true} onPress={() => setFilters((current) => ({ ...current, on_sale: true, is_active: undefined, product_type: undefined }))} />
    </ScrollView><Pressable accessibilityLabel={t('products.moreFiltersLabel')} onPress={() => setFiltersOpen(true)} style={styles.filterButton}><MaterialCommunityIcons name="tune-variant" size={20} color={colors.blue} /></Pressable></View>
    {loading ? <StateLoading label={t('products.syncing')} /> : null}
    {error ? <StateError message={error} onRetry={() => void load()} /> : null}
    {!loading && !error && !products.length ? <EmptyProducts filtered={Boolean(search || filters.is_active !== undefined || filters.product_type || filters.on_sale || filters.category_id)} /> : null}
    {!loading && !error ? <View style={styles.productList}>{products.map((product) => <ProductListRow key={product.id} product={product} onChanged={() => void load()} />)}</View> : null}
    {!loading && !error && page.current < page.last ? <AppButton label={loadingMore ? t('products.loadingMore') : t('products.loadMore')} variant="secondary" disabled={loadingMore} onPress={() => void load(page.current + 1, true)} style={styles.loadMore} /> : null}
    <ProductFilterSheet visible={filtersOpen} filters={filters} categories={categories} onClose={() => setFiltersOpen(false)} onApply={(next) => { setFilters(next); setFiltersOpen(false); }} />
  </Screen>;
}

function ProductListRow({ product, onChanged }: { product: Product; onChanged: () => void }) {
  const { t, type, stock } = useLabels();
  const [menuOpen, setMenuOpen] = useState(false);
  const palette = productStatusColor(product.is_active);
  const toggle = async (kind: 'status' | 'mute') => {
    try { if (kind === 'status') await productService.toggleStatus(product.id); else await productService.toggleMute(product.id); setMenuOpen(false); onChanged(); } catch (error) { Alert.alert(t('products.couldNotUpdate'), getErrorMessage(error)); }
  };
  const duplicate = async () => {
    try { const copy = await productService.duplicateProduct(product.id); setMenuOpen(false); onChanged(); router.push({ pathname: '/product-editor', params: { id: String(copy.id) } }); } catch (error) { Alert.alert(t('products.couldNotDuplicate'), getErrorMessage(error)); }
  };
  const remove = () => Alert.alert(t('products.deleteTitle'), t('products.deleteCopy', { name: product.name }), [{ text: t('common.cancel'), style: 'cancel' }, { text: t('common.delete'), style: 'destructive', onPress: () => void productService.deleteProduct(product.id).then(onChanged).catch((error) => Alert.alert(t('products.couldNotDelete'), getErrorMessage(error))) }]);
  return <><Pressable accessibilityRole="button" onPress={() => router.push({ pathname: '/product-details/[id]', params: { id: String(product.id) } })} style={styles.productRow}>
    <ProductImage source={product.images?.[0]} type={product.product_type} />
    <View style={styles.productCopy}><View style={styles.productNameRow}><Text numberOfLines={1} style={styles.productName}>{product.name}</Text>{product.is_muted ? <MaterialCommunityIcons name="volume-off" size={14} color="#718096" /> : null}</View><Text numberOfLines={1} style={styles.productMeta}>{product.sku ? `${product.sku} · ` : ''}{type(product.product_type)}</Text><View style={styles.productFooter}><Text style={styles.productPrice}>{money(product.price)}</Text><Text style={[styles.stockText, product.stock_status === 'out_of_stock' && { color: colors.red }]}>{product.stock_quantity} · {stock(product.stock_status)}</Text></View></View>
    <View style={styles.productEnd}><View style={[styles.badge, { backgroundColor: palette.bg }]}><Text style={[styles.badgeText, { color: palette.text }]}>{product.is_active ? t('products.filter.live') : t('products.filter.inactive')}</Text></View><Pressable accessibilityLabel={t('products.actionsFor', { name: product.name })} hitSlop={8} onPress={(event) => { event.stopPropagation(); setMenuOpen(true); }} style={styles.rowMenu}><MaterialCommunityIcons name="dots-vertical" size={20} color="#4D627C" /></Pressable></View>
  </Pressable><BottomSheet visible={menuOpen} title={product.name} subtitle={t('products.rowActions')} onClose={() => setMenuOpen(false)}><ActionSheetItem icon="eye-outline" label={t('products.viewDetails')} onPress={() => { setMenuOpen(false); router.push({ pathname: '/product-details/[id]', params: { id: String(product.id) } }); }} /><ActionSheetItem icon="pencil-outline" label={t('products.editProduct')} onPress={() => { setMenuOpen(false); router.push({ pathname: '/product-editor', params: { id: String(product.id) } }); }} /><ActionSheetItem icon="content-copy" label={t('products.duplicateProduct')} onPress={() => void duplicate()} /><ActionSheetItem icon={product.is_active ? 'pause-circle-outline' : 'play-circle-outline'} label={product.is_active ? t('products.setInactive') : t('products.publishProduct')} onPress={() => void toggle('status')} /><ActionSheetItem icon={product.is_muted ? 'volume-high' : 'volume-off'} label={product.is_muted ? t('products.unmuteProduct') : t('products.muteProduct')} onPress={() => void toggle('mute')} /><ActionSheetItem icon="delete-outline" label={t('products.deleteProduct')} destructive onPress={() => { setMenuOpen(false); remove(); }} /></BottomSheet></>;
}

function ProductFilterSheet({ visible, filters, categories, onClose, onApply }: { visible: boolean; filters: ProductListParams; categories: ProductCategory[]; onClose: () => void; onApply: (value: ProductListParams) => void }) {
  const { t, type } = useLabels();
  const [draft, setDraft] = useState(filters);
  const close = () => { setDraft(filters); onClose(); };
  return <BottomSheet visible={visible} title={t('products.filterTitle')} subtitle={t('products.filterSubtitle')} onClose={close}>
    <SheetLabel label={t('products.filterAvailability')} />
    <ChoiceRow choices={[[t('products.filter.all'), undefined], [t('products.filter.live'), true], [t('products.filter.inactive'), false]] as const} selected={draft.is_active} onSelect={(is_active) => setDraft((next) => ({ ...next, is_active }))} />
    <SheetLabel label={t('products.filterType')} /><ChoiceRow choices={[[t('products.filterAllTypes'), undefined], ...(Object.keys(TYPE_KEY) as ProductType[]).map((value) => [type(value), value] as const)]} selected={draft.product_type} onSelect={(product_type) => setDraft((next) => ({ ...next, product_type }))} />
    <SheetLabel label={t('products.filterCategory')} /><ChoiceRow choices={[[t('products.filterAllCategories'), undefined], ...categories.filter((category) => !category.parent_id).map((category) => [category.name, category.id] as const)]} selected={draft.category_id} onSelect={(category_id) => setDraft((next) => ({ ...next, category_id }))} />
    <SheetLabel label={t('products.filterSortBy')} /><ChoiceRow choices={[[t('products.sort.newest'), 'created_at:desc'], [t('products.sort.oldest'), 'created_at:asc'], [t('products.sort.nameAsc'), 'name:asc'], [t('products.sort.priceAsc'), 'price:asc'], [t('products.sort.priceDesc'), 'price:desc']] as const} selected={`${draft.sort_by ?? 'created_at'}:${draft.sort_order ?? 'desc'}`} onSelect={(value) => { const [sort_by, sort_order] = String(value).split(':'); setDraft((next) => ({ ...next, sort_by, sort_order: sort_order as 'asc' | 'desc' })); }} />
    <View style={styles.filterActions}><AppButton label={t('products.filterClear')} variant="secondary" onPress={() => { const cleared: ProductListParams = { sort_by: 'created_at', sort_order: 'desc' }; setDraft(cleared); onApply(cleared); }} style={styles.actionFlex} /><AppButton label={t('products.filterApply')} onPress={() => { onApply(draft); }} style={styles.actionFlex} /></View>
  </BottomSheet>;
}

export function ProductDetailsScreen() {
  const { t, type, stock } = useLabels();
  const { id } = useLocalSearchParams<{ id: string }>();
  const productId = Number(id);
  const [product, setProduct] = useState<Product | null>(null);
  const [variants, setVariants] = useState<ProductVariant[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionsOpen, setActionsOpen] = useState(false);
  const [variantOpen, setVariantOpen] = useState(false);
  const load = useCallback(async () => {
    if (!Number.isFinite(productId) || productId < 1) { setError(t('productDetails.invalidLink')); setLoading(false); return; }
    try { setError(null); const next = await productService.getProduct(productId); setProduct(next); setVariants(await productService.getVariants(productId)); }
    catch (cause) { setError(getErrorMessage(cause)); } finally { setLoading(false); }
  }, [productId, t]);
  useAutoRefresh(load);
  const remove = () => Alert.alert(t('productDetails.deleteTitle'), t('productDetails.deleteCopy'), [{ text: t('common.cancel'), style: 'cancel' }, { text: t('common.delete'), style: 'destructive', onPress: () => void productService.deleteProduct(productId).then(() => router.replace('/products')).catch((cause) => setError(getErrorMessage(cause))) }]);
  const quickUpdate = async (action: 'status' | 'mute') => { try { const next = action === 'status' ? await productService.toggleStatus(productId) : await productService.toggleMute(productId); setProduct(next); setActionsOpen(false); } catch (cause) { setError(getErrorMessage(cause)); } };
  const duplicate = async () => { try { const copy = await productService.duplicateProduct(productId); setActionsOpen(false); router.push({ pathname: '/product-editor', params: { id: String(copy.id) } }); } catch (cause) { setError(getErrorMessage(cause)); } };
  return <Screen contentStyle={styles.screenBottom}>
    <AppHeader title={t('productDetails.title')} left={<MaterialCommunityIcons name="arrow-left" size={22} color="#3E5877" />} onLeftPress={() => goBack('/products')} right={<MaterialCommunityIcons name="dots-horizontal" size={22} color="#3E5877" />} onRightPress={() => setActionsOpen(true)} />
    {loading ? <StateLoading label={t('productDetails.loading')} /> : null}{error && !product ? <StateError message={error} onRetry={() => void load()} /> : null}
    {product ? <View style={styles.detailBody}>{error ? <InlineError message={error} /> : null}<ProductGallery product={product} /><View style={styles.detailTitleRow}><View style={styles.detailTitleCopy}><Text style={styles.overline}>{type(product.product_type)}</Text><Text style={styles.detailName}>{product.name}</Text><Text style={styles.detailSku}>{product.sku || t('productDetails.skuGenerated')}</Text></View><StatusPill active={product.is_active} /></View>
      <View style={styles.topProductActions}><AppButton label={t('products.editProduct')} onPress={() => router.push({ pathname: '/product-editor', params: { id: String(product.id) } })} icon={<MaterialCommunityIcons name="pencil-outline" size={17} color="#FFFFFF" />} style={styles.actionFlex} /><AppButton label={t('productDetails.actions')} variant="secondary" onPress={() => setActionsOpen(true)} icon={<MaterialCommunityIcons name="dots-horizontal" size={18} color={colors.blue} />} style={styles.actionFlex} /></View>
      <DetailCard title={t('productCard.priceAvailability')} icon="tag-outline"><ValueRow label={t('productCard.sellingPrice')} value={money(product.price)} strong /><ValueRow label={t('productCard.compareAt')} value={product.compare_at_price ? money(product.compare_at_price) : undefined} /><ValueRow label={t('productCard.costPrice')} value={product.cost_price ? money(product.cost_price) : undefined} /><ValueRow label={t('productCard.inventory')} value={`${product.stock_quantity} · ${stock(product.stock_status)}`} /><ValueRow label={t('productCard.shipping')} value={product.shipping_type === 'fixed' ? t('productCard.fixedFee', { amount: money(product.shipping_fee) }) : t('productCard.freeShipping')} />{product.sale_start_date || product.sale_end_date ? <ValueRow label={t('productCard.saleSchedule')} value={[dateText(product.sale_start_date), dateText(product.sale_end_date)].filter(Boolean).join(' – ')} /> : null}</DetailCard>
      <DetailCard title={t('productInfo.title')} icon="information-outline"><ValueRow label={t('productInfo.category')} value={[product.category?.name, product.sub_category?.name].filter(Boolean).join(' · ')} /><ValueRow label={t('productInfo.visibility')} value={`${product.is_active ? t('productInfo.published') : t('products.filter.inactive')}${product.is_featured ? ` · ${t('productInfo.featured')}` : ''}${product.is_muted ? ` · ${t('productInfo.muted')}` : ''}`} />{product.short_description ? <DetailText label={t('productInfo.shortDescription')} value={product.short_description} /> : null}{product.description ? <DetailText label={t('productInfo.description')} value={product.description} /> : null}</DetailCard>
      <ProductSpecifications product={product} />
      <DetailCard title={t('productVariants.title')} icon="shape-outline"><Text style={styles.cardHelp}>{t('productVariants.help')}</Text>{variants.length ? variants.map((variant) => <VariantRow key={variant.id} variant={variant} onChanged={load} />) : <Text style={styles.emptySmall}>{t('productVariants.none')}</Text>}<AppButton label={t('productVariants.add')} variant="secondary" onPress={() => setVariantOpen(true)} icon={<MaterialCommunityIcons name="plus" size={17} color={colors.blue} />} style={styles.cardButton} /></DetailCard>
      <DetailCard title={t('productDiscovery.title')} icon="magnify"><ValueRow label={t('productDiscovery.views')} value={String(product.view_count ?? 0)} /><ValueRow label={t('productDiscovery.rating')} value={t('productDiscovery.rating', { rating: product.rating ?? 0, count: product.review_count ?? 0 })} /><ValueRow label={t('productDiscovery.sold')} value={String(product.total_sold ?? 0)} /><ValueRow label={t('productDiscovery.revenue')} value={product.total_revenue !== undefined ? money(product.total_revenue) : undefined} /><ValueRow label={t('productDiscovery.model3d')} value={product.model_3d_url ?? undefined} /><ValueRow label={t('productDiscovery.tryOn')} value={product.try_on_image ?? undefined} /><ValueRow label={t('productDiscovery.seoTitle')} value={product.meta_title ?? undefined} /><DetailText label={t('productDiscovery.seoDescription')} value={product.meta_description} /><ValueRow label={t('productDiscovery.keywords')} value={product.meta_keywords ?? undefined} /></DetailCard>
    </View> : null}
    {product ? <><BottomSheet visible={actionsOpen} title={product.name} subtitle={t('products.catalogueControls')} onClose={() => setActionsOpen(false)}><ActionSheetItem icon="pencil-outline" label={t('products.editProduct')} onPress={() => { setActionsOpen(false); router.push({ pathname: '/product-editor', params: { id: String(product.id) } }); }} /><ActionSheetItem icon="content-copy" label={t('products.duplicateProduct')} onPress={() => void duplicate()} /><ActionSheetItem icon={product.is_active ? 'pause-circle-outline' : 'play-circle-outline'} label={product.is_active ? t('products.setInactive') : t('products.publishProduct')} onPress={() => void quickUpdate('status')} /><ActionSheetItem icon={product.is_muted ? 'volume-high' : 'volume-off'} label={product.is_muted ? t('products.unmuteProduct') : t('products.muteProduct')} onPress={() => void quickUpdate('mute')} /><ActionSheetItem icon="delete-outline" label={t('products.deleteProduct')} destructive onPress={() => { setActionsOpen(false); remove(); }} /></BottomSheet><VariantEditorSheet visible={variantOpen} productId={product.id} onClose={() => setVariantOpen(false)} onSaved={() => { setVariantOpen(false); void load(); }} /></> : null}
  </Screen>;
}

export function ProductCreateScreen() {
  const { t } = useLabels();
  const [categories, setCategories] = useState<ProductCategory[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null);
  const load = useCallback(async () => { try { setLoading(true); setError(null); setCategories(await productService.getCategories()); } catch (cause) { setError(getErrorMessage(cause)); } finally { setLoading(false); } }, []);
  useEffect(() => { const timer = setTimeout(() => { void load(); }, 0); return () => clearTimeout(timer); }, [load]);
  const supported = categories.filter((category) => !category.parent_id && PRODUCT_CATEGORY_TYPES[category.slug]);
  return <Screen contentStyle={styles.screenBottom}><AppHeader title={t('productCreate.title')} left={<MaterialCommunityIcons name="arrow-left" size={22} color="#3E5877" />} onLeftPress={() => router.back()} right={null} /><View style={styles.intro}><Text style={styles.overline}>{t('productCreate.step')}</Text><Text style={styles.title}>{t('productCreate.pageTitle')}</Text><Text style={styles.subtitle}>{t('productCreate.pageSubtitle')}</Text></View>{loading ? <StateLoading label={t('productCreate.loading')} /> : null}{error ? <StateError message={error} onRetry={() => void load()} /> : null}<View style={styles.categoryList}>{supported.map((category) => <CategoryTile key={category.id} category={category} />)}</View></Screen>;
}

function CategoryTile({ category }: { category: ProductCategory }) {
  const { t, type: typeLabel } = useLabels();
  const type = PRODUCT_CATEGORY_TYPES[category.slug]; const icon: Record<ProductType, React.ComponentProps<typeof MaterialCommunityIcons>['name']> = { frame: 'glasses', sunglasses: 'weather-sunny', contact_lens: 'circle-double', eye_hygiene: 'bottle-tonic-plus-outline', accessory: 'shopping-outline' };
  return <Pressable accessibilityRole="button" onPress={() => router.push({ pathname: '/product-editor', params: { categoryId: String(category.id), productType: type } })} style={styles.categoryTile}><View style={styles.categoryIcon}><MaterialCommunityIcons name={icon[type]} size={25} color={colors.blue} /></View><View style={styles.categoryCopy}><Text style={styles.categoryName}>{category.name}</Text><Text style={styles.categoryText}>{typeLabel(type)} · {t('productCreate.categorySpecific')}</Text></View><MaterialCommunityIcons name="chevron-right" size={22} color="#8494A9" /></Pressable>;
}

type FormState = {
  categoryId?: number; subCategoryId?: number; productType: ProductType; name: string; sku: string; shortDescription: string; description: string; images: string[];
  price: string; compareAtPrice: string; costPrice: string; stockQuantity: string; stockStatus: StockStatus; saleStart: string; saleEnd: string; featured: boolean; active: boolean; shippingType: 'free' | 'fixed'; shippingFee: string;
  frameShape: string; frameMaterial: string; frameColor: string; gender: 'men' | 'women' | 'unisex' | 'kids'; lensType: string; lensIndexes: string; treatments: string;
  baseCurves: string; diameters: string; powersRange: string; replacementFrequency: string; contactBrand: string; contactColor: string; contactMaterial: string; contactType: string; hasUv: boolean; canSleep: boolean; waterContent: string; medicalDevice: boolean;
  sizeVolume: string; packType: string; expiry: string; model3d: string; tryOnImage: string; colorImages: string; mmCalibers: string; lensColors: string; sizeVariants: string; hygieneVariants: string; contactUnitConfig: string;
  metaTitle: string; metaDescription: string; metaKeywords: string;
};
const defaultForm = (type: ProductType, categoryId?: number): FormState => ({ categoryId, productType: type, name: '', sku: '', shortDescription: '', description: '', images: [], price: '', compareAtPrice: '', costPrice: '', stockQuantity: '0', stockStatus: 'in_stock', saleStart: '', saleEnd: '', featured: false, active: true, shippingType: 'free', shippingFee: '0', frameShape: '', frameMaterial: '', frameColor: '', gender: 'unisex', lensType: '', lensIndexes: '', treatments: '', baseCurves: '', diameters: '', powersRange: '', replacementFrequency: '', contactBrand: '', contactColor: '', contactMaterial: '', contactType: '', hasUv: false, canSleep: false, waterContent: '', medicalDevice: false, sizeVolume: '', packType: '', expiry: '', model3d: '', tryOnImage: '', colorImages: '', mmCalibers: '', lensColors: '', sizeVariants: '', hygieneVariants: '', contactUnitConfig: '', metaTitle: '', metaDescription: '', metaKeywords: '' });

function productToForm(product: Product): FormState {
  const form = defaultForm(product.product_type, product.category_id ?? undefined);
  return { ...form, subCategoryId: product.sub_category_id ?? undefined, name: product.name, sku: product.sku ?? '', shortDescription: product.short_description ?? '', description: product.description ?? '', images: product.images ?? [], price: String(product.price ?? ''), compareAtPrice: product.compare_at_price == null ? '' : String(product.compare_at_price), costPrice: product.cost_price == null ? '' : String(product.cost_price), stockQuantity: String(product.stock_quantity ?? 0), stockStatus: product.stock_status, saleStart: product.sale_start_date?.slice(0, 10) ?? '', saleEnd: product.sale_end_date?.slice(0, 10) ?? '', featured: Boolean(product.is_featured), active: product.is_active !== false, shippingType: product.shipping_type ?? 'free', shippingFee: String(product.shipping_fee ?? 0), frameShape: product.frame_shape ?? '', frameMaterial: product.frame_material ?? '', frameColor: product.frame_color ?? '', gender: product.gender ?? 'unisex', lensType: product.lens_type ?? '', lensIndexes: listFrom(product.lens_index_options), treatments: listFrom(product.treatment_options), baseCurves: listFrom(product.base_curve_options), diameters: listFrom(product.diameter_options), powersRange: product.powers_range ?? '', replacementFrequency: product.replacement_frequency ?? '', contactBrand: product.contact_lens_brand ?? '', contactColor: product.contact_lens_color ?? '', contactMaterial: product.contact_lens_material ?? '', contactType: product.contact_lens_type ?? '', hasUv: Boolean(product.has_uv_filter), canSleep: Boolean(product.can_sleep_with), waterContent: product.water_content ?? '', medicalDevice: Boolean(product.is_medical_device), sizeVolume: product.size_volume ?? '', packType: product.pack_type ?? '', expiry: product.expiry_date?.slice(0, 10) ?? '', model3d: product.model_3d_url ?? '', tryOnImage: product.try_on_image ?? '', colorImages: listFrom(product.color_images), mmCalibers: product.mm_calibers ? JSON.stringify(product.mm_calibers, null, 2) : '', lensColors: product.lens_colors?.length ? JSON.stringify(product.lens_colors, null, 2) : '', sizeVariants: product.size_volume_variants?.length ? JSON.stringify(product.size_volume_variants, null, 2) : '', hygieneVariants: product.eye_hygiene_variants?.length ? JSON.stringify(product.eye_hygiene_variants, null, 2) : '', contactUnitConfig: product.contact_lens_unit_config ? JSON.stringify(product.contact_lens_unit_config, null, 2) : '', metaTitle: product.meta_title ?? '', metaDescription: product.meta_description ?? '', metaKeywords: product.meta_keywords ?? '' };
}

export function ProductEditorScreen() {
  const { t, language } = useLanguage();
  const { type: typeLabel } = useLabels();
  const params = useLocalSearchParams<{ id?: string; categoryId?: string; productType?: ProductType }>();
  const editingId = Number(params.id); const isEdit = Number.isFinite(editingId) && editingId > 0;
  const [form, setForm] = useState<FormState>(() => defaultForm(params.productType && TYPE_KEY[params.productType] ? params.productType : 'frame', Number(params.categoryId) || undefined));
  const [categories, setCategories] = useState<ProductCategory[]>([]); const [config, setConfig] = useState<CategoryFieldConfig | null>(null); const [loading, setLoading] = useState(isEdit); const [saving, setSaving] = useState(false); const [error, setError] = useState<string | null>(null); const [step, setStep] = useState(0); const [categoryOpen, setCategoryOpen] = useState(false); const [subcategoryOpen, setSubcategoryOpen] = useState(false);
  const reload = useCallback(async () => { try { setLoading(true); setError(null); const allCategories = await productService.getCategories(); setCategories(allCategories); if (isEdit) { const product = await productService.getProduct(editingId); const next = productToForm(product); setForm(next); if (next.categoryId) setConfig(await productService.getFieldConfig(next.categoryId)); } else if (Number(params.categoryId)) setConfig(await productService.getFieldConfig(Number(params.categoryId))); } catch (cause) { setError(getErrorMessage(cause)); } finally { setLoading(false); } }, [editingId, isEdit, params.categoryId]);
  useEffect(() => { const timer = setTimeout(() => { void reload(); }, 0); return () => clearTimeout(timer); }, [reload]);
  const set = <K extends keyof FormState>(key: K, value: FormState[K]) => setForm((current) => ({ ...current, [key]: value }));
  const selectCategory = async (category: ProductCategory) => { const productType = PRODUCT_CATEGORY_TYPES[category.slug]; if (!productType) return; setForm((current) => ({ ...defaultForm(productType, category.id), images: current.images })); setConfig(await productService.getFieldConfig(category.id).catch(() => null)); setCategoryOpen(false); setStep(0); };
  const enabled = (field: string) => !config?.enabled_fields?.length || config.enabled_fields.includes(field);
  const uploadImages = async () => { try { const permission = await ImagePicker.requestMediaLibraryPermissionsAsync(); if (!permission.granted) { Alert.alert(t('productEditor.error.photoPermission'), t('productEditor.error.photoPermissionCopy')); return; } const result = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], allowsMultipleSelection: true, quality: 0.82, selectionLimit: 8 }); if (result.canceled) return; setSaving(true); const urls = await Promise.all(result.assets.map((asset) => productService.uploadImage({ uri: asset.uri, fileName: asset.fileName, mimeType: asset.mimeType }))); set('images', [...form.images, ...urls]); } catch (cause) { setError(getErrorMessage(cause)); } finally { setSaving(false); } };
  const parseJson = <T,>(value: string, label: string): T | undefined => { if (!value.trim()) return undefined; try { return JSON.parse(value) as T; } catch { throw new Error(t('productEditor.error.invalidJson', { field: label })); } };
  const submit = async () => { try { if (!form.categoryId) throw new Error(t('productEditor.error.categoryRequired')); if (!form.name.trim()) throw new Error(t('productEditor.error.nameRequired')); if (!form.price.trim() || toNumber(form.price, -1) < 0) throw new Error(t('productEditor.error.priceRequired')); if (!Number.isInteger(toNumber(form.stockQuantity, -1)) || toNumber(form.stockQuantity, -1) < 0) throw new Error(t('productEditor.error.stockInvalid')); const data: ProductInput = { name: form.name.trim(), category_id: form.categoryId, sub_category_id: form.subCategoryId, sku: cleanOptional(form.sku), short_description: cleanOptional(form.shortDescription), description: cleanOptional(form.description), product_type: form.productType, price: toNumber(form.price), compare_at_price: form.compareAtPrice ? toNumber(form.compareAtPrice) : undefined, cost_price: form.costPrice ? toNumber(form.costPrice) : undefined, sale_start_date: cleanOptional(form.saleStart), sale_end_date: cleanOptional(form.saleEnd), stock_quantity: toNumber(form.stockQuantity), stock_status: form.stockStatus, images: form.images, is_featured: form.featured, is_active: form.active, shipping_type: form.shippingType, shipping_fee: toNumber(form.shippingFee), meta_title: cleanOptional(form.metaTitle), meta_description: cleanOptional(form.metaDescription), meta_keywords: cleanOptional(form.metaKeywords), frame_shape: cleanOptional(form.frameShape), frame_material: cleanOptional(form.frameMaterial), frame_color: cleanOptional(form.frameColor), gender: form.gender, lens_type: cleanOptional(form.lensType), lens_index_options: listTo(form.lensIndexes), treatment_options: listTo(form.treatments), base_curve_options: listTo(form.baseCurves), diameter_options: listTo(form.diameters), powers_range: cleanOptional(form.powersRange), replacement_frequency: cleanOptional(form.replacementFrequency), contact_lens_brand: cleanOptional(form.contactBrand), contact_lens_color: cleanOptional(form.contactColor), contact_lens_material: cleanOptional(form.contactMaterial), contact_lens_type: cleanOptional(form.contactType), has_uv_filter: form.hasUv, can_sleep_with: form.canSleep, water_content: cleanOptional(form.waterContent), is_medical_device: form.medicalDevice, size_volume: cleanOptional(form.sizeVolume), pack_type: cleanOptional(form.packType), expiry_date: cleanOptional(form.expiry), model_3d_url: cleanOptional(form.model3d), try_on_image: cleanOptional(form.tryOnImage), color_images: listTo(form.colorImages), mm_calibers: parseJson(form.mmCalibers, t('configuration.field.mm_calibers')), lens_colors: parseJson(form.lensColors, t('configuration.field.lens_colors')), size_volume_variants: parseJson(form.sizeVariants, t('configuration.field.size_volume_variants')), eye_hygiene_variants: parseJson(form.hygieneVariants, t('configuration.field.eye_hygiene_variants')), contact_lens_unit_config: parseJson(form.contactUnitConfig, t('configuration.field.contact_lens_unit_config')) }; setSaving(true); setError(null); const saved = isEdit ? await productService.updateProduct(editingId, data) : await productService.createProduct(data); router.replace({ pathname: '/product-details/[id]', params: { id: String(saved.id) } }); } catch (cause) { setError(getErrorMessage(cause)); } finally { setSaving(false); } };
  const steps = ['productEditor.stepBasics', 'productEditor.stepPricing', 'productEditor.stepSpecs', 'productEditor.stepPublishing'];
  const selectedCategory = categories.find((category) => category.id === form.categoryId);
  return <Screen contentStyle={styles.screenBottom}><AppHeader title={t(isEdit ? 'productEditor.editTitle' : 'productEditor.newTitle')} left={<MaterialCommunityIcons name="arrow-left" size={22} color="#3E5877" />} onLeftPress={() => router.back()} right={null} />{loading ? <StateLoading label={t('productEditor.loading')} /> : <View style={styles.editorBody}><StepIndicator steps={steps.map((key) => t(key))} active={step} /><Text style={styles.editorHeading}>{t(steps[step])}</Text><Text style={styles.editorSubheading}>{t(step === 0 ? 'productEditor.subBasics' : step === 1 ? 'productEditor.subPricing' : step === 2 ? 'productEditor.subSpecs' : 'productEditor.subPublishing', step === 2 ? { type: typeLabel(form.productType).toLocaleLowerCase(language) } : undefined)}</Text>{error ? <InlineError message={error} /> : null}{step === 0 ? <BasicsStep form={form} set={set} categories={categories} onOpenCategory={() => setCategoryOpen(true)} onOpenSubcategory={() => setSubcategoryOpen(true)} onUpload={uploadImages} saving={saving} /> : null}{step === 1 ? <PricingStep form={form} set={set} /> : null}{step === 2 ? <SpecificationsStep form={form} set={set} enabled={enabled} /> : null}{step === 3 ? <PublishingStep form={form} set={set} /> : null}<View style={styles.editorActions}>{step > 0 ? <AppButton label={t('productEditor.back')} variant="secondary" onPress={() => setStep((value) => value - 1)} style={styles.actionFlex} /> : <AppButton label={t('productEditor.cancel')} variant="secondary" onPress={() => router.back()} style={styles.actionFlex} />}{step < steps.length - 1 ? <AppButton label={t('productEditor.continue')} onPress={() => setStep((value) => value + 1)} style={styles.actionFlex} /> : <AppButton label={saving ? t('productEditor.saving') : t(isEdit ? 'productEditor.saveChanges' : 'productEditor.createProduct')} disabled={saving} onPress={() => void submit()} style={styles.actionFlex} />}</View></View>}<BottomSheet visible={categoryOpen} title={t('productEditor.categoryTitle')} subtitle={t('productEditor.categorySubtitle')} onClose={() => setCategoryOpen(false)}>{categories.filter((category) => !category.parent_id && PRODUCT_CATEGORY_TYPES[category.slug]).map((category) => <ActionSheetItem key={category.id} icon="shape-outline" label={category.name} onPress={() => void selectCategory(category)} />)}</BottomSheet><BottomSheet visible={subcategoryOpen} title={t('editorBasics.subcategory')} subtitle={t('editorBasics.subcategorySheetSubtitle')} onClose={() => setSubcategoryOpen(false)}><ActionSheetItem icon="close-circle-outline" label={t('editorBasics.noSubcategory')} onPress={() => { set('subCategoryId', undefined); setSubcategoryOpen(false); }} />{(selectedCategory?.children ?? []).map((category) => <ActionSheetItem key={category.id} icon="folder-outline" label={category.name} onPress={() => { set('subCategoryId', category.id); setSubcategoryOpen(false); }} />)}</BottomSheet></Screen>;
}

function BasicsStep({ form, set, categories, onOpenCategory, onOpenSubcategory, onUpload, saving }: { form: FormState; set: <K extends keyof FormState>(key: K, value: FormState[K]) => void; categories: ProductCategory[]; onOpenCategory: () => void; onOpenSubcategory: () => void; onUpload: () => void; saving: boolean }) {
  const { t, type: typeLabel } = useLabels();
  const category = categories.find((item) => item.id === form.categoryId); const subcategories = category?.children ?? [];
  return <><SelectPress label={t('editorBasics.category')} value={category?.name ?? typeLabel(form.productType)} onPress={onOpenCategory} /><FormInput label={t('editorBasics.name')} value={form.name} onChangeText={(value) => set('name', value)} placeholder={t('editorBasics.namePlaceholder')} required /><FormInput label={t('editorBasics.sku')} value={form.sku} onChangeText={(value) => set('sku', value)} placeholder={t('editorBasics.skuPlaceholder')} /><FormInput label={t('editorBasics.shortDescription')} value={form.shortDescription} onChangeText={(value) => set('shortDescription', value)} placeholder={t('editorBasics.shortDescriptionPlaceholder')} multiline /><FormInput label={t('editorBasics.fullDescription')} value={form.description} onChangeText={(value) => set('description', value)} placeholder={t('editorBasics.fullDescriptionPlaceholder')} multiline /><SelectPress label={t('editorBasics.subcategory')} value={subcategories.find((item) => item.id === form.subCategoryId)?.name ?? (subcategories.length ? t('editorBasics.subcategorySelect') : t('editorBasics.subcategoryNone'))} onPress={onOpenSubcategory} /><ImageEditor images={form.images} busy={saving} onAdd={onUpload} onRemove={(url) => set('images', form.images.filter((image) => image !== url))} /></>;
}

function PricingStep({ form, set }: { form: FormState; set: <K extends keyof FormState>(key: K, value: FormState[K]) => void }) {
  const { t, stock: stockLabel } = useLabels();
  return <><FormInput label={t('editorPricing.sellingPrice')} value={form.price} onChangeText={(value) => set('price', value)} keyboardType="decimal-pad" required /><FormInput label={t('editorPricing.compareAt')} value={form.compareAtPrice} onChangeText={(value) => set('compareAtPrice', value)} keyboardType="decimal-pad" helper={t('editorPricing.compareAtHelper')} /><FormInput label={t('editorPricing.costPrice')} value={form.costPrice} onChangeText={(value) => set('costPrice', value)} keyboardType="decimal-pad" /><DateField label={t('editorPricing.saleStart')} value={form.saleStart} onChange={(value) => set('saleStart', value)} /><DateField label={t('editorPricing.saleEnd')} value={form.saleEnd} onChange={(value) => set('saleEnd', value)} minimumDate={form.saleStart ? new Date(`${form.saleStart}T12:00:00`) : undefined} /><FormInput label={t('editorPricing.stockQuantity')} value={form.stockQuantity} onChangeText={(value) => set('stockQuantity', value.replace(/\D/g, ''))} keyboardType="number-pad" required /><ChoiceField label={t('editorPricing.stockStatus')} choices={(Object.keys(STOCK_KEY) as StockStatus[]).map((value) => [stockLabel(value), value] as [string, StockStatus])} selected={form.stockStatus} onSelect={(value) => set('stockStatus', value)} /><ChoiceField label={t('editorPricing.shipping')} choices={[[t('editorPricing.freeShipping'), 'free'], [t('editorPricing.fixedFee'), 'fixed']]} selected={form.shippingType} onSelect={(value) => set('shippingType', value)} />{form.shippingType === 'fixed' ? <FormInput label={t('editorPricing.shippingFee')} value={form.shippingFee} onChangeText={(value) => set('shippingFee', value)} keyboardType="decimal-pad" /> : null}</>;
}

function SpecificationsStep({ form, set, enabled }: { form: FormState; set: <K extends keyof FormState>(key: K, value: FormState[K]) => void; enabled: (field: string) => boolean }) {
  const { t } = useLanguage();
  const eyewear = form.productType === 'frame' || form.productType === 'sunglasses'; const contact = form.productType === 'contact_lens'; const hygiene = form.productType === 'eye_hygiene';
  return <>{eyewear ? <><FormInput label={t('editorSpecs.frameShape')} value={form.frameShape} onChangeText={(value) => set('frameShape', value)} placeholder={t('editorSpecs.frameShapePlaceholder')} /><FormInput label={t('editorSpecs.frameMaterial')} value={form.frameMaterial} onChangeText={(value) => set('frameMaterial', value)} placeholder={t('editorSpecs.frameMaterialPlaceholder')} /><FormInput label={t('editorSpecs.frameColor')} value={form.frameColor} onChangeText={(value) => set('frameColor', value)} /><ChoiceField label={t('editorSpecs.gender')} choices={[[t('editorSpecs.women'), 'women'], [t('editorSpecs.men'), 'men'], [t('editorSpecs.unisex'), 'unisex'], [t('editorSpecs.kids'), 'kids']]} selected={form.gender} onSelect={(value) => set('gender', value)} /><FormInput label={t('editorSpecs.lensType')} value={form.lensType} onChangeText={(value) => set('lensType', value)} placeholder={t('editorSpecs.lensTypePlaceholder')} /><FormInput label={t('editorSpecs.lensIndexes')} value={form.lensIndexes} onChangeText={(value) => set('lensIndexes', value)} placeholder={t('editorSpecs.lensIndexesPlaceholder')} helper={t('editorSpecs.commaHint')} /><FormInput label={t('editorSpecs.treatments')} value={form.treatments} onChangeText={(value) => set('treatments', value)} placeholder={t('editorSpecs.treatmentsPlaceholder')} helper={t('editorSpecs.commaHint')} /></> : null}{contact ? <><FormInput label={t('editorSpecs.brand')} value={form.contactBrand} onChangeText={(value) => set('contactBrand', value)} /><FormInput label={t('editorSpecs.contactType')} value={form.contactType} onChangeText={(value) => set('contactType', value)} placeholder={t('editorSpecs.contactTypePlaceholder')} /><FormInput label={t('editorSpecs.material')} value={form.contactMaterial} onChangeText={(value) => set('contactMaterial', value)} /><FormInput label={t('editorSpecs.color')} value={form.contactColor} onChangeText={(value) => set('contactColor', value)} /><FormInput label={t('editorSpecs.baseCurves')} value={form.baseCurves} onChangeText={(value) => set('baseCurves', value)} helper={t('editorSpecs.commaSeparated')} /><FormInput label={t('editorSpecs.diameters')} value={form.diameters} onChangeText={(value) => set('diameters', value)} helper={t('editorSpecs.commaSeparated')} /><FormInput label={t('editorSpecs.powerRange')} value={form.powersRange} onChangeText={(value) => set('powersRange', value)} placeholder="-0.50 to -8.00" /><FormInput label={t('editorSpecs.replacement')} value={form.replacementFrequency} onChangeText={(value) => set('replacementFrequency', value)} /><FormInput label={t('editorSpecs.waterContent')} value={form.waterContent} onChangeText={(value) => set('waterContent', value)} placeholder="e.g. 58%" /><SwitchField label={t('editorSpecs.uvFilter')} value={form.hasUv} onChange={(value) => set('hasUv', value)} /><SwitchField label={t('editorSpecs.sleepWith')} value={form.canSleep} onChange={(value) => set('canSleep', value)} /><SwitchField label={t('editorSpecs.medicalDevice')} value={form.medicalDevice} onChange={(value) => set('medicalDevice', value)} /></> : null}{hygiene ? <><FormInput label={t('editorSpecs.sizeVolume')} value={form.sizeVolume} onChangeText={(value) => set('sizeVolume', value)} placeholder="e.g. 100 ml" /><FormInput label={t('editorSpecs.packType')} value={form.packType} onChangeText={(value) => set('packType', value)} placeholder={t('editorSpecs.packTypePlaceholder')} /><DateField label={t('editorSpecs.expiry')} value={form.expiry} onChange={(value) => set('expiry', value)} /></> : null}{enabled('lens_colors') ? <JsonField label={t('editorSpecs.lensColors')} value={form.lensColors} onChangeText={(value) => set('lensColors', value)} helper={t('editorSpecs.lensColorsHelper')} /> : null}{enabled('size_volume_variants') ? <JsonField label={t('editorSpecs.sizeVariants')} value={form.sizeVariants} onChangeText={(value) => set('sizeVariants', value)} helper={t('editorSpecs.sizeVariantsHelper')} /> : null}{enabled('eye_hygiene_variants') ? <JsonField label={t('editorSpecs.hygieneVariants')} value={form.hygieneVariants} onChangeText={(value) => set('hygieneVariants', value)} helper={t('editorSpecs.hygieneVariantsHelper')} /> : null}{enabled('contact_lens_unit_config') ? <JsonField label={t('editorSpecs.contactUnitConfig')} value={form.contactUnitConfig} onChangeText={(value) => set('contactUnitConfig', value)} helper={t('editorSpecs.contactUnitConfigHelper')} /> : null}</>;
}

function PublishingStep({ form, set }: { form: FormState; set: <K extends keyof FormState>(key: K, value: FormState[K]) => void }) {
  const { t } = useLanguage();
  return <><SwitchField label={t('editorPublishing.publish')} value={form.active} onChange={(value) => set('active', value)} helper={t('editorPublishing.publishHelper')} /><SwitchField label={t('editorPublishing.feature')} value={form.featured} onChange={(value) => set('featured', value)} helper={t('editorPublishing.featureHelper')} /><FormInput label={t('editorPublishing.model3d')} value={form.model3d} onChangeText={(value) => set('model3d', value)} placeholder="https://…" /><FormInput label={t('editorPublishing.tryOn')} value={form.tryOnImage} onChangeText={(value) => set('tryOnImage', value)} placeholder="https://…" /><FormInput label={t('editorPublishing.colorImages')} value={form.colorImages} onChangeText={(value) => set('colorImages', value)} helper={t('editorPublishing.colorImagesHelper')} /><JsonField label={t('editorPublishing.mmCalibers')} value={form.mmCalibers} onChangeText={(value) => set('mmCalibers', value)} helper={t('editorPublishing.mmCalibersHelper')} /><FormInput label={t('editorPublishing.seoTitle')} value={form.metaTitle} onChangeText={(value) => set('metaTitle', value)} /><FormInput label={t('editorPublishing.seoDescription')} value={form.metaDescription} onChangeText={(value) => set('metaDescription', value)} multiline /><FormInput label={t('editorPublishing.seoKeywords')} value={form.metaKeywords} onChangeText={(value) => set('metaKeywords', value)} placeholder={t('editorPublishing.seoKeywordsPlaceholder')} /></>;
}

function ProductSpecifications({ product }: { product: Product }) {
  const { t } = useLanguage();
  const rows: [string, string | undefined][] = [['Frame shape', product.frame_shape ?? undefined], ['Frame material', product.frame_material ?? undefined], ['Frame color', product.frame_color ?? undefined], ['Gender', product.gender ? humanize(product.gender) : undefined], ['Lens type', product.lens_type ?? undefined], ['Lens index options', product.lens_index_options?.join(', ')], ['Treatments', product.treatment_options?.join(', ')], ['Contact brand', product.contact_lens_brand ?? undefined], ['Contact type', product.contact_lens_type ?? undefined], ['Contact material', product.contact_lens_material ?? undefined], ['Contact color', product.contact_lens_color ?? undefined], ['Base curves', product.base_curve_options?.join(', ')], ['Diameters', product.diameter_options?.join(', ')], ['Power range', product.powers_range ?? undefined], ['Replacement', product.replacement_frequency ?? undefined], ['Water content', product.water_content ?? undefined], ['UV filter', product.has_uv_filter === undefined ? undefined : product.has_uv_filter ? 'Yes' : 'No'], ['Sleep with lenses', product.can_sleep_with === undefined ? undefined : product.can_sleep_with ? 'Yes' : 'No'], ['Medical device', product.is_medical_device === undefined ? undefined : product.is_medical_device ? 'Yes' : 'No'], ['Size / volume', product.size_volume ?? undefined], ['Pack type', product.pack_type ?? undefined], ['Expiry date', dateText(product.expiry_date) ?? undefined]];
  const lensColors = product.lens_colors?.map((color) => color.name).join(', ');
  const hasData = rows.some(([, value]) => Boolean(value)) || lensColors || product.size_volume_variants?.length || product.eye_hygiene_variants?.length || product.contact_lens_unit_config;
  if (!hasData) return null;
  return <DetailCard title={t('editorSpecs.title')} icon="tune-variant">{rows.map(([label, value]) => <ValueRow key={label} label={label} value={value} />)}<ValueRow label={t('editorSpecs.lensColors')} value={lensColors} />{product.size_volume_variants?.length ? <DetailText label={t('editorSpecs.sizeVariants')} value={product.size_volume_variants.map((item) => `${item.size_volume} · ${money(item.price)} · ${item.stock_quantity} stock`).join('\n')} /> : null}{product.eye_hygiene_variants?.length ? <DetailText label={t('editorSpecs.hygieneVariants')} value={product.eye_hygiene_variants.map((item) => `${item.name} · ${money(item.price)}`).join('\n')} /> : null}{product.contact_lens_unit_config ? <DetailText label={t('editorSpecs.contactUnitConfig')} value={JSON.stringify(product.contact_lens_unit_config, null, 2)} /> : null}</DetailCard>;
}

function VariantEditorSheet({ visible, productId, onClose, onSaved }: { visible: boolean; productId: number; onClose: () => void; onSaved: () => void }) {
  const { t } = useLanguage();
  const { stock: stockLabel } = useLabels();
  const [name, setName] = useState(''); const [color, setColor] = useState(''); const [price, setPrice] = useState(''); const [stock, setStock] = useState('0'); const [status, setStatus] = useState<StockStatus>('in_stock'); const [saving, setSaving] = useState(false); const [error, setError] = useState<string | null>(null);
  const reset = () => { setName(''); setColor(''); setPrice(''); setStock('0'); setStatus('in_stock'); setError(null); };
  const close = () => { reset(); onClose(); };
  const save = async () => { try { if (!name.trim()) throw new Error(t('variantEditor.error.name')); if (toNumber(stock, -1) < 0) throw new Error(t('variantEditor.error.stock')); setSaving(true); const data: ProductVariantInput = { color_name: name.trim(), color_code: cleanOptional(color), price: price ? toNumber(price) : undefined, stock_quantity: toNumber(stock), stock_status: status }; await productService.createVariant(productId, data); reset(); onSaved(); } catch (cause) { setError(getErrorMessage(cause)); } finally { setSaving(false); } };
  return <BottomSheet visible={visible} title={t('productVariants.add')} subtitle={t('variantEditor.subtitle')} onClose={close}>{error ? <InlineError message={error} /> : null}<FormInput label={t('variantEditor.colorName')} value={name} onChangeText={setName} placeholder={t('variantEditor.colorNamePlaceholder2')} required /><FormInput label={t('variantEditor.colorCode')} value={color} onChangeText={setColor} placeholder="#1D2738" /><FormInput label={t('variantEditor.price')}  value={price} onChangeText={setPrice} keyboardType="decimal-pad" helper={t('variantEditor.priceHelper')} /><FormInput label={t('editorPricing.stockQuantity')} value={stock} onChangeText={(value) => setStock(value.replace(/\D/g, ''))} keyboardType="number-pad" /><ChoiceField label={t('editorPricing.stockStatus')} choices={(Object.keys(STOCK_KEY) as StockStatus[]).map((value) => [stockLabel(value), value] as [string, StockStatus])} selected={status} onSelect={setStatus} /><AppButton label={saving ? t('productEditor.saving') : t('variantEditor.save')} disabled={saving} onPress={() => void save()} style={styles.sheetButton} /></BottomSheet>;
}

function VariantRow({ variant, onChanged }: { variant: ProductVariant; onChanged: () => void }) {
  const { t } = useLanguage();
  const { stock: stockLabel } = useLabels();
  const [open, setOpen] = useState(false); const remove = () => Alert.alert(t('variantRow.deleteTitle'), t('variantRow.deleteCopy'), [{ text: t('common.cancel'), style: 'cancel' }, { text: t('common.delete'), style: 'destructive', onPress: () => void productService.deleteVariant(variant.id).then(onChanged).catch((error) => Alert.alert(t('variantRow.couldNotDelete'), getErrorMessage(error))) }]);
  return <View style={styles.variantRow}><View style={[styles.colorDot, { backgroundColor: variant.color_code || '#DCE9F8' }]} /><View style={styles.variantCopy}><Text style={styles.variantName}>{variant.color_name}</Text><Text style={styles.variantMeta}>{variant.price ? money(variant.price) : t('variantRow.productPrice')} · {t('variantRow.stock', { count: variant.stock_quantity })} · {stockLabel(variant.stock_status)}</Text></View>{variant.is_default ? <Text style={styles.defaultText}>{t('variantRow.default')}</Text> : null}<Pressable onPress={() => setOpen(true)} hitSlop={8}><MaterialCommunityIcons name="dots-vertical" size={20} color="#718096" /></Pressable><BottomSheet visible={open} title={variant.color_name} subtitle={t('variantRow.actions')} onClose={() => setOpen(false)}><ActionSheetItem icon="star-outline" label={t('variantRow.setDefault')} onPress={() => void productService.setDefaultVariant(variant.id).then(() => { setOpen(false); onChanged(); }).catch((error) => Alert.alert(t('variantRow.couldNotUpdate'), getErrorMessage(error)))} /><ActionSheetItem icon="delete-outline" label={t('variantRow.delete')} destructive onPress={() => { setOpen(false); remove(); }} /></BottomSheet></View>;
}

function ProductGallery({ product }: { product: Product }) {
  const { t } = useLanguage(); return <View style={styles.gallery}>{product.images?.length ? <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.galleryScroll}>{product.images.map((image, index) => <Image key={`${image}-${index}`} source={{ uri: image }} style={styles.galleryImage} />)}</ScrollView> : <View style={styles.galleryEmpty}><MaterialCommunityIcons name="image-outline" size={37} color="#78A5D8" /><Text style={styles.galleryEmptyText}>{t('gallery.empty')}</Text></View>}</View>; }
function ProductImage({ source, type }: { source?: string; type: ProductType }) { const icon: Record<ProductType, React.ComponentProps<typeof MaterialCommunityIcons>['name']> = { frame: 'glasses', sunglasses: 'weather-sunny', contact_lens: 'circle-double', eye_hygiene: 'bottle-tonic-plus-outline', accessory: 'shopping-outline' }; return source ? <Image source={{ uri: source }} style={styles.productImage} /> : <View style={styles.productPlaceholder}><MaterialCommunityIcons name={icon[type]} size={27} color="#40719A" /></View>; }
function StatusPill({ active }: { active: boolean }) { const palette = productStatusColor(active); return <View style={[styles.statusPill, { backgroundColor: palette.bg }]}><Text style={[styles.statusPillText, { color: palette.text }]}>{active ? 'Live' : 'Inactive'}</Text></View>; }
function DetailCard({ title, icon, children }: { title: string; icon: React.ComponentProps<typeof MaterialCommunityIcons>['name']; children: ReactNode }) { return <View style={styles.detailCard}><View style={styles.detailCardHead}><View style={styles.detailCardIcon}><MaterialCommunityIcons name={icon} size={18} color={colors.blue} /></View><Text style={styles.detailCardTitle}>{title}</Text></View>{children}</View>; }
function ValueRow({ label, value, strong }: { label: string; value?: string; strong?: boolean }) { if (!value) return null; return <View style={styles.valueRow}><Text style={styles.valueLabel}>{label}</Text><Text selectable numberOfLines={3} style={[styles.valueText, strong && styles.valueStrong]}>{value}</Text></View>; }
function DetailText({ label, value }: { label: string; value?: string | null }) { if (!value) return null; return <View style={styles.detailTextWrap}><Text style={styles.valueLabel}>{label}</Text><Text selectable style={styles.detailText}>{value}</Text></View>; }
function FilterPill({ label, active, onPress }: { label: string; active: boolean; onPress: () => void }) { return <Pressable onPress={onPress} style={[styles.filterPill, active && styles.filterPillActive]}><Text style={[styles.filterPillText, active && styles.filterPillTextActive]}>{label}</Text></Pressable>; }
function SearchField({ value, onChange, onClose, placeholder }: { value: string; onChange: (value: string) => void; onClose: () => void; placeholder: string }) { return <View style={styles.searchField}><MaterialCommunityIcons name="magnify" size={20} color="#718096" /><TextInput autoFocus value={value} onChangeText={onChange} placeholder={placeholder} placeholderTextColor="#7C8BA0" style={styles.searchInput} /><Pressable onPress={onClose} hitSlop={8}><MaterialCommunityIcons name="close" size={19} color="#718096" /></Pressable></View>; }
function SheetLabel({ label }: { label: string }) { return <Text style={styles.sheetLabel}>{label}</Text>; }
function ChoiceRow<T extends string | number | boolean | undefined>({ choices, selected, onSelect }: { choices: readonly (readonly [string, T])[]; selected: T; onSelect: (value: T) => void }) { return <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.choiceRow}>{choices.map(([label, value]) => <Pressable key={`${label}-${String(value)}`} onPress={() => onSelect(value)} style={[styles.choice, selected === value && styles.choiceActive]}><Text style={[styles.choiceText, selected === value && styles.choiceTextActive]}>{label}</Text></Pressable>)}</ScrollView>; }
function SelectPress({ label, value, onPress }: { label: string; value: string; onPress: () => void }) { return <View style={styles.fieldGroup}><Text style={styles.fieldLabel}>{label}</Text><Pressable onPress={onPress} style={styles.selectField}><Text numberOfLines={1} style={styles.selectText}>{value}</Text><MaterialCommunityIcons name="chevron-down" size={20} color="#718096" /></Pressable></View>; }
function FormInput({ label, helper, required, multiline, ...props }: { label: string; helper?: string; required?: boolean; multiline?: boolean } & React.ComponentProps<typeof TextInput>) { return <View style={styles.fieldGroup}><Text style={styles.fieldLabel}>{label}{required ? <Text style={{ color: colors.red }}> *</Text> : null}</Text><TextInput style={[styles.textField, multiline && styles.textArea]} placeholderTextColor="#7C8BA0" multiline={multiline} textAlignVertical={multiline ? 'top' : 'center'} {...props} />{helper ? <Text style={styles.fieldHelper}>{helper}</Text> : null}</View>; }
function JsonField({ label, helper, ...props }: { label: string; helper?: string } & React.ComponentProps<typeof TextInput>) { return <FormInput label={label} helper={helper} multiline autoCapitalize="none" autoCorrect={false} {...props} />; }
function ChoiceField<T extends string>({ label, choices, selected, onSelect }: { label: string; choices: [string, T][]; selected: T; onSelect: (value: T) => void }) { return <View style={styles.fieldGroup}><Text style={styles.fieldLabel}>{label}</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.choiceRow}>{choices.map(([text, value]) => <Pressable key={value} onPress={() => onSelect(value)} style={[styles.choice, selected === value && styles.choiceActive]}><Text style={[styles.choiceText, selected === value && styles.choiceTextActive]}>{text}</Text></Pressable>)}</ScrollView></View>; }
function SwitchField({ label, value, onChange, helper }: { label: string; value: boolean; onChange: (value: boolean) => void; helper?: string }) { return <View style={styles.switchField}><View style={styles.switchCopy}><Text style={styles.fieldLabel}>{label}</Text>{helper ? <Text style={styles.fieldHelper}>{helper}</Text> : null}</View><Switch value={value} onValueChange={onChange} trackColor={{ false: '#D6DFEB', true: '#8AB9F2' }} thumbColor={value ? colors.blue : '#FFFFFF'} /></View>; }
function ImageEditor({ images, busy, onAdd, onRemove }: { images: string[]; busy: boolean; onAdd: () => void; onRemove: (url: string) => void }) {
  const { t } = useLanguage(); return <View style={styles.fieldGroup}><Text style={styles.fieldLabel}>{t('gallery.title')}</Text><Text style={styles.fieldHelper}>{t('gallery.help')}</Text><View style={styles.uploadRow}>{images.map((image) => <View key={image} style={styles.uploadImageWrap}><Image source={{ uri: image }} style={styles.uploadImage} /><Pressable accessibilityLabel={t('gallery.remove')} onPress={() => onRemove(image)} style={styles.removeImage}><MaterialCommunityIcons name="close" size={13} color="#FFFFFF" /></Pressable></View>)}<Pressable disabled={busy} onPress={onAdd} style={styles.uploadTile}>{busy ? <ActivityIndicator color={colors.blue} /> : <><MaterialCommunityIcons name="image-plus" size={22} color={colors.blue} /><Text style={styles.uploadLabel}>{t('gallery.upload')}</Text></>}</Pressable></View></View>; }
function StepIndicator({ steps, active }: { steps: string[]; active: number }) { return <View style={styles.steps}>{steps.map((label, index) => <View key={label} style={styles.stepItem}><View style={[styles.stepDot, index <= active && styles.stepDotActive]}><Text style={[styles.stepNumber, index <= active && styles.stepNumberActive]}>{index + 1}</Text></View>{index < steps.length - 1 ? <View style={[styles.stepLine, index < active && styles.stepLineActive]} /> : null}</View>)}</View>; }
function ActionSheetItem({ icon, label, onPress, destructive }: { icon: React.ComponentProps<typeof MaterialCommunityIcons>['name']; label: string; onPress: () => void; destructive?: boolean }) { return <Pressable onPress={onPress} style={styles.sheetItem}><View style={[styles.sheetItemIcon, destructive && styles.sheetItemDanger]}><MaterialCommunityIcons name={icon} size={20} color={destructive ? colors.red : colors.blue} /></View><Text style={[styles.sheetItemText, destructive && { color: colors.red }]}>{label}</Text><MaterialCommunityIcons name="chevron-right" size={20} color="#8B9AAF" /></Pressable>; }
function StateLoading({ label }: { label: string }) { return <View style={styles.state}><ActivityIndicator size="large" color={colors.blue} /><Text style={styles.stateText}>{label}</Text></View>; }
function StateError({ message, onRetry }: { message: string; onRetry: () => void }) {
  const { t } = useLanguage(); return <View style={styles.stateCard}><MaterialCommunityIcons name="cloud-alert-outline" size={27} color={colors.red} /><Text style={styles.stateTitle}>{t('state.loadFailed')}</Text><Text style={styles.stateText}>{message}</Text><AppButton label={t('state.tryAgain')} variant="secondary" onPress={onRetry} style={styles.stateButton} /></View>; }
function EmptyProducts({ filtered }: { filtered: boolean }) {
  const { t } = useLanguage(); return <View style={styles.stateCard}><MaterialCommunityIcons name="package-variant-closed" size={31} color={colors.blue} /><Text style={styles.stateTitle}>{t(filtered ? 'state.noMatchingProducts' : 'state.catalogueReady')}</Text><Text style={styles.stateText}>{t(filtered ? 'state.tryOtherFilter' : 'state.addFirstProduct')}</Text>{!filtered ? <AppButton label={t('products.addProductLabel')} onPress={() => router.push('/product-create')} style={styles.stateButton} /> : null}</View>; }
function InlineError({ message }: { message: string }) { return <View style={styles.inlineError}><MaterialCommunityIcons name="alert-circle-outline" size={18} color={colors.red} /><Text style={styles.inlineErrorText}>{message}</Text></View>; }

